    public function testEveryGeneratedMethodReachesMockAndDecodesItsResponse(): void
    {
        $baseUrl = getenv('SDK_METHOD_TEST_BASE_URL');
        if ($baseUrl === false || $baseUrl === '') {
            self::markTestSkipped('Run ./scripts/test to start the generated mock server.');
        }
        $config = new ClientConfig();
        $config->baseUrl = $baseUrl;
        SdkConfig::configure($config);
        $cases = self::fixtureCases();
        self::assertNotEmpty($cases);
        foreach ($cases as $case) {
            $method = new ReflectionMethod($case['owner'], $case['methodName']);
            $arguments = [];
            $position = 0;
            $outcome = null;
            $ownedNames = array_map(
                static fn(ReflectionParameter $parameter): string => self::normalized($parameter->getName()),
                $method->getParameters(),
            );
            foreach ($method->getParameters() as $parameter) {
                $type = $parameter->getType();
                if ($type instanceof ReflectionNamedType && $type->getName() === ClientConfig::class) {
                    $arguments[] = SdkConfig::getConfig();
                } elseif ($type instanceof ReflectionNamedType && $type->getName() === RequestOptions::class) {
                    // Per-call options are the SDK's own, never an operation argument.
                    $arguments[] = null;
                } elseif ($type instanceof ReflectionNamedType && $type->getName() === \Closure::class) {
                    // A callback companion delivers its one outcome through the closure.
                    $arguments[] = static function (?\Throwable $error, mixed $result) use (&$outcome): void {
                        $outcome = [$error, $result];
                    };
                } elseif ($type instanceof ReflectionNamedType && $type->getName() === 'array') {
                    // Only an object-style carrier is documented by an array shape, and it takes
                    // every argument, even beside a field named like it ($params). A positional
                    // array parameter takes its own value.
                    $own = self::argument($case['arguments'], $parameter->getName());
                    $value = !str_contains((string) $method->getDocComment(), '@param array{')
                        && self::hasArgument($case['arguments'], $parameter->getName()) && ($own === null || is_array($own))
                        ? $own
                        : $case['arguments'];
                    $upload = static fn(mixed $item): mixed => is_string($item) ? new SdkUploadFile($item, 'mock.bin', 'application/octet-stream') : $item;
                    // A list of files takes each item as an upload, as a single file does.
                    if (is_array($value) && preg_match('/@param list<SdkUploadFile>(\|\S+)? \$' . $parameter->getName() . '\b/', (string) $method->getDocComment())) {
                        $value = array_map($upload, $value);
                    }
                    // A carrier field takes the value its positional parameter would, by the type its shape names.
                    if (is_array($value) && preg_match('/@param array\{(.*)\} \$' . $parameter->getName() . '\b/', (string) $method->getDocComment(), $shape)) {
                        $namespace = $method->getDeclaringClass()->getNamespaceName();
                        preg_match_all("/'(\w+)'\??:(list<SdkUploadFile>|[\w|]+)(?=,|$)/", $shape[1], $fields, PREG_SET_ORDER);
                        foreach ($fields as [, $field, $union]) {
                            if (!array_key_exists($field, $value)) {
                                continue;
                            }
                            $value[$field] = $union === 'list<SdkUploadFile>' && is_array($value[$field])
                                ? array_map($upload, $value[$field])
                                : self::convertTo(
                                    array_map(
                                        static fn(string $name): string => self::matchesBuiltin($name, null) === null ? $namespace . '\\' . $name : $name,
                                        explode('|', $union),
                                    ),
                                    $value[$field],
                                    self::argument($case['structuredArguments'], $field),
                                );
                        }
                    }
                    $arguments[] = $value;
                } else {
                    $value = self::argument($case['arguments'], $parameter->getName());
                    $structuredValue = self::argument($case['structuredArguments'], $parameter->getName());
                    $named = self::hasArgument($case['arguments'], $parameter->getName());
                    // A case name another parameter owns is never borrowed positionally.
                    while (
                        !$named
                        && isset($case['argumentOrder'][$position])
                        && in_array(self::normalized($case['argumentOrder'][$position]), $ownedNames, true)
                    ) {
                        $position++;
                    }
                    if (!$named && isset($case['argumentOrder'][$position])) {
                        $orderedName = $case['argumentOrder'][$position++];
                        $value = self::argument($case['arguments'], $orderedName);
                        $structuredValue = self::argument($case['structuredArguments'], $orderedName);
                    }
                    // A named null is an omitted optional argument, not a value.
                    $arguments[] = $value === null && $parameter->isDefaultValueAvailable()
                        ? $parameter->getDefaultValue()
                        : self::convert($parameter, $value, $structuredValue);
                }
            }
            $config->baseUrl = $case['response']['kind'] === 'error'
                ? $baseUrl . '/__mockStatus/' . $case['response']['status']
                : $baseUrl;
            if ($case['response']['kind'] === 'error') {
                try {
                    $method->invokeArgs(null, $arguments);
                    $error = null;
                } catch (\Throwable $thrown) {
                    $error = $thrown;
                }
                if (!$error instanceof SdkHttpError) {
                    self::fail($case['id'] . ' did not raise its declared error');
                }
                self::assertSame($case['response']['status'], $error->statusCode, $case['id']);
                self::assertTrue(
                    self::representative(self::normal($error->data), $case['response']['expected']),
                    $case['id'] . ' decoded an error body that differs from the mock',
                );
                continue;
            }
            if ($case['response']['kind'] === 'rejected') {
                try {
                    $result = $method->invokeArgs(null, $arguments);
                    // A stream decodes an event only when it is read.
                    if ($case['mode'] === 'stream' && $result instanceof \Traversable) {
                        foreach ($result as $event) {
                            break;
                        }
                    }
                    $error = is_array($outcome) ? $outcome[0] : null;
                } catch (\Throwable $thrown) {
                    $error = $thrown;
                }
                self::assertInstanceOf(SdkResponseDecodeError::class, $error, $case['id'] . ' decoded a body its schema refuses');
                continue;
            }
            $actual = $method->invokeArgs(null, $arguments);
            if ($case['mode'] === 'callback') {
                if (!is_array($outcome)) {
                    throw new \RuntimeException($case['id'] . ' did not deliver an outcome to its callback.');
                }
                [$error, $actual] = $outcome;
                if ($error instanceof \Throwable) {
                    throw $error;
                }
            }
            if ($case['mode'] === 'stream' && $actual instanceof \Traversable) {
                foreach ($actual as $event) {
                    $actual = $event;
                    break;
                }
            }
            $response = $case['response'];
            if ($response['kind'] === 'empty') {
                self::assertNull($actual, $case['id']);
            } elseif ($response['kind'] === 'bytes') {
                if (!is_string($actual)) {
                    throw new \RuntimeException('Generated binary SDK method did not return a string.');
                }
                self::assertSame($response['byteLength'], strlen($actual), $case['id']);
            } else {
                self::assertTrue(
                    self::representative(self::normal($actual), $response['expected']),
                    $case['id'] . ' decoded a response that differs from the mock',
                );
            }
        }
    }
